/// Ref type alias for [`ScpStatementPledges`].
pub type ScpStatementPledgesRef = XdrRef<ScpStatementPledges>;

impl ScpStatementPledges {
    /// Validate the XDR encoding of ScpStatementPledges at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: ScpStatementType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                ScpStatementType::Prepare => {
                    let l = ScpStatementPrepare::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScpStatementType::Confirm => {
                    let l = ScpStatementConfirm::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScpStatementType::Externalize => {
                    let l = ScpStatementExternalize::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScpStatementType::Nominate => {
                    let l = ScpNomination::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ScpStatementPledges>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ScpStatementPledges>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ScpStatementPledges> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<ScpStatementType, Error> {
        let v = read_i32_at(buf, self.offset())?;
        v.try_into()
    }

    /// Access the `Prepare` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_prepare(&self, buf: &[u8]) -> Result<Option<XdrRef<ScpStatementPrepare>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScpStatementType::Prepare {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScpStatementPrepare::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `Confirm` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_confirm(&self, buf: &[u8]) -> Result<Option<XdrRef<ScpStatementConfirm>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScpStatementType::Confirm {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScpStatementConfirm::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `Externalize` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_externalize(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<ScpStatementExternalize>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScpStatementType::Externalize {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScpStatementExternalize::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `Nominate` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_nominate(&self, buf: &[u8]) -> Result<Option<XdrRef<ScpNomination>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScpStatementType::Nominate {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScpNomination::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`ScpStatementPledges`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ScpStatementPledges, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ScpStatementPledges::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

