/// Ref type alias for [`ConfigSettingEntry`].
pub type ConfigSettingEntryRef = XdrRef<ConfigSettingEntry>;

impl ConfigSettingEntry {
    /// Validate the XDR encoding of ConfigSettingEntry at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: ConfigSettingId = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                ConfigSettingId::ContractMaxSizeBytes => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractComputeV0 => {
                    check_bounds(buf, pos, 28)?;
                    pos = pos.checked_add(28).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractLedgerCostV0 => {
                    check_bounds(buf, pos, 84)?;
                    pos = pos.checked_add(84).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractHistoricalDataV0 => {
                    check_bounds(buf, pos, 8)?;
                    pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractEventsV0 => {
                    check_bounds(buf, pos, 12)?;
                    pos = pos.checked_add(12).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractBandwidthV0 => {
                    check_bounds(buf, pos, 16)?;
                    pos = pos.checked_add(16).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractCostParamsCpuInstructions => {
                    let l = ContractCostParams::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractCostParamsMemoryBytes => {
                    let l = ContractCostParams::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractDataKeySizeBytes => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractDataEntrySizeBytes => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::StateArchival => {
                    check_bounds(buf, pos, 48)?;
                    pos = pos.checked_add(48).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractExecutionLanes => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::LiveSorobanStateSizeWindow => {
                    pos = pos
                        .checked_add(skip_vec_fixed(buf, pos, 8, u32::MAX)?)
                        .ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::EvictionIterator => {
                    check_bounds(buf, pos, 16)?;
                    pos = pos.checked_add(16).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractParallelComputeV0 => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ContractLedgerCostExtV0 => {
                    check_bounds(buf, pos, 12)?;
                    pos = pos.checked_add(12).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::ScpTiming => {
                    check_bounds(buf, pos, 20)?;
                    pos = pos.checked_add(20).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::FrozenLedgerKeys => {
                    let l = FrozenLedgerKeys::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::FrozenLedgerKeysDelta => {
                    let l = FrozenLedgerKeysDelta::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::FreezeBypassTxs => {
                    let l = FreezeBypassTxs::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ConfigSettingId::FreezeBypassTxsDelta => {
                    let l = FreezeBypassTxsDelta::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ConfigSettingEntry>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ConfigSettingEntry>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

