/// Ref type alias for [`ScSpecTypeDef`].
pub type ScSpecTypeDefRef = XdrRef<ScSpecTypeDef>;

impl ScSpecTypeDef {
    /// Validate the XDR encoding of ScSpecTypeDef at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: ScSpecType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                ScSpecType::Val => {}
                ScSpecType::Bool => {}
                ScSpecType::Void => {}
                ScSpecType::Error => {}
                ScSpecType::U32 => {}
                ScSpecType::I32 => {}
                ScSpecType::U64 => {}
                ScSpecType::I64 => {}
                ScSpecType::Timepoint => {}
                ScSpecType::Duration => {}
                ScSpecType::U128 => {}
                ScSpecType::I128 => {}
                ScSpecType::U256 => {}
                ScSpecType::I256 => {}
                ScSpecType::Bytes => {}
                ScSpecType::String => {}
                ScSpecType::Symbol => {}
                ScSpecType::Address => {}
                ScSpecType::MuxedAddress => {}
                ScSpecType::Option => {
                    let l = ScSpecTypeOption::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::Result => {
                    let l = ScSpecTypeResult::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::Vec => {
                    let l = ScSpecTypeVec::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::Map => {
                    let l = ScSpecTypeMap::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::Tuple => {
                    let l = ScSpecTypeTuple::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::BytesN => {
                    check_bounds(buf, pos, 4)?;
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                }
                ScSpecType::Udt => {
                    let l = ScSpecTypeUdt::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ScSpecTypeDef>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ScSpecTypeDef>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

