    /// Access the `VoidV0` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_void_v0(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<ScSpecUdtUnionCaseVoidV0>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScSpecUdtUnionCaseV0Kind::VoidV0 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScSpecUdtUnionCaseVoidV0::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `TupleV0` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_tuple_v0(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<ScSpecUdtUnionCaseTupleV0>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ScSpecUdtUnionCaseV0Kind::TupleV0 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScSpecUdtUnionCaseTupleV0::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

