    pub fn as_or(&self, buf: &[u8]) -> Result<Option<XdrRef<VecM<ClaimPredicate, 2>>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimPredicateType::Or {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, arm_off, 2, |buf, off| {
            let mut p = off;
            let l = ClaimPredicate::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(arm_off, total)).map(Some)
    }

    /// Access the `Not` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_not(&self, buf: &[u8]) -> Result<Option<XdrRef<Option<Box<ClaimPredicate>>>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimPredicateType::Not {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let flag = read_u32_at(buf, arm_off)?;
        match flag {
            0 => Ok(XdrRef::new(arm_off, 4)),
            1 => {
                let inner_off = arm_off.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                let inner_len =
                    ClaimPredicate::xdr_ref_validate(buf, inner_off, &mut RefLimits::none())?;
                Ok(XdrRef::new(
                    arm_off,
                    4u32.checked_add(inner_len).ok_or(Error::LengthExceedsMax)?,
                ))
            }
            _ => Err(Error::Invalid),
        }
        .map(Some)
    }

    /// Access the `BeforeAbsoluteTime` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_before_absolute_time(&self, buf: &[u8]) -> Result<Option<XdrRef<i64>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimPredicateType::BeforeAbsoluteTime {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(arm_off, 8)).map(Some)
    }

