/// Ref type alias for [`ContractCodeEntryExt`].
pub type ContractCodeEntryExtRef = XdrRef<ContractCodeEntryExt>;

impl ContractCodeEntryExt {
    /// Validate the XDR encoding of ContractCodeEntryExt at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            #[allow(clippy::match_same_arms)]
            match dv {
                0 => {}
                1 => {
                    let l = ContractCodeEntryV1::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ContractCodeEntryExt>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ContractCodeEntryExt>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ContractCodeEntryExt> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<i32, Error> {
        read_i32_at(buf, self.offset())
    }

    /// Access the `V1` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v1(&self, buf: &[u8]) -> Result<Option<XdrRef<ContractCodeEntryV1>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 1 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ContractCodeEntryV1::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`ContractCodeEntryExt`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ContractCodeEntryExt, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ContractCodeEntryExt::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

/// Ref type alias for [`ContractCodeEntry`].
pub type ContractCodeEntryRef = XdrRef<ContractCodeEntry>;

impl ContractCodeEntry {
    /// Validate the XDR encoding of ContractCodeEntry at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let l = ContractCodeEntryExt::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            check_bounds(buf, pos, 32)?;
            pos = pos.checked_add(32).ok_or(Error::LengthExceedsMax)?;
            {
                pos = pos
                    .checked_add(skip_var_opaque(buf, pos, u32::MAX)?)
                    .ok_or(Error::LengthExceedsMax)?;
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ContractCodeEntry>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ContractCodeEntry>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ContractCodeEntry> {
    /// Access field `ext` at a variable offset.
    #[inline]
    pub fn ext(&self, buf: &[u8]) -> Result<XdrRef<ContractCodeEntryExt>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ContractCodeEntryExt::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `hash` (variable offset — scans preceding fields).
    pub fn hash(&self, buf: &[u8]) -> Result<XdrRef<Hash>, Error> {
        let mut pos = self.offset();
        {
            let l = ContractCodeEntryExt::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        Ok(XdrRef::new(field_off, 32))
    }

    /// Access field `code` (variable offset — scans preceding fields).
    pub fn code(&self, buf: &[u8]) -> Result<XdrRef<BytesM>, Error> {
        let mut pos = self.offset();
        {
            let l = ContractCodeEntryExt::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        pos = pos.checked_add(32).ok_or(Error::LengthExceedsMax)?;
        let field_off = pos;
        let (_, total) = var_opaque_xdr_len(buf, field_off, u32::MAX)?;
        Ok(XdrRef::new(field_off, total))
    }

    /// Materialize the full owned [`ContractCodeEntry`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ContractCodeEntry, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ContractCodeEntry::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .ext(buf)?
            .cmp_in(buf, &other.ext(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .hash(buf)?
            .cmp_in(buf, &other.hash(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .code(buf)?
            .cmp_in(buf, &other.code(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

