/// Ref type alias for [`LedgerEntryData`].
pub type LedgerEntryDataRef = XdrRef<LedgerEntryData>;

impl LedgerEntryData {
    /// Validate the XDR encoding of LedgerEntryData at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: LedgerEntryType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                LedgerEntryType::Account => {
                    let l = AccountEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Trustline => {
                    let l = TrustLineEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Offer => {
                    let l = OfferEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Data => {
                    let l = DataEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ClaimableBalance => {
                    let l = ClaimableBalanceEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::LiquidityPool => {
                    let l = LiquidityPoolEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ContractData => {
                    let l = ContractDataEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ContractCode => {
                    let l = ContractCodeEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ConfigSetting => {
                    let l = ConfigSettingEntry::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Ttl => {
                    check_bounds(buf, pos, 36)?;
                    pos = pos.checked_add(36).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<LedgerEntryData>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<LedgerEntryData>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

