/// Ref type alias for [`LedgerKeyContractData`].
pub type LedgerKeyContractDataRef = XdrRef<LedgerKeyContractData>;

impl LedgerKeyContractData {
    /// Validate the XDR encoding of LedgerKeyContractData at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let l = ScAddress::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            {
                let l = ScVal::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            check_bounds(buf, pos, 4)?;
            pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<LedgerKeyContractData>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<LedgerKeyContractData>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<LedgerKeyContractData> {
    /// Access field `contract` at a variable offset.
    #[inline]
    pub fn contract(&self, buf: &[u8]) -> Result<XdrRef<ScAddress>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ScAddress::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `key` (variable offset — scans preceding fields).
    pub fn key(&self, buf: &[u8]) -> Result<XdrRef<ScVal>, Error> {
        let mut pos = self.offset();
        {
            let l = ScAddress::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l = ScVal::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `durability` (variable offset — scans preceding fields).
    pub fn durability(&self, buf: &[u8]) -> Result<XdrRef<ContractDataDurability>, Error> {
        let mut pos = self.offset();
        {
            let l = ScAddress::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        {
            let l = ScVal::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        Ok(XdrRef::new(field_off, 4))
    }

    /// Materialize the full owned [`LedgerKeyContractData`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<LedgerKeyContractData, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        LedgerKeyContractData::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .contract(buf)?
            .cmp_in(buf, &other.contract(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .key(buf)?
            .cmp_in(buf, &other.key(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .durability(buf)?
            .cmp_in(buf, &other.durability(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

