/// Ref type alias for [`LedgerKey`].
pub type LedgerKeyRef = XdrRef<LedgerKey>;

impl LedgerKey {
    /// Validate the XDR encoding of LedgerKey at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: LedgerEntryType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                LedgerEntryType::Account => {
                    let l = LedgerKeyAccount::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Trustline => {
                    let l = LedgerKeyTrustLine::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Offer => {
                    let l = LedgerKeyOffer::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Data => {
                    let l = LedgerKeyData::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ClaimableBalance => {
                    let l = LedgerKeyClaimableBalance::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::LiquidityPool => {
                    let l = LedgerKeyLiquidityPool::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ContractData => {
                    let l = LedgerKeyContractData::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ContractCode => {
                    let l = LedgerKeyContractCode::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::ConfigSetting => {
                    let l = LedgerKeyConfigSetting::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                LedgerEntryType::Ttl => {
                    let l = LedgerKeyTtl::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<LedgerKey>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<LedgerKey>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

