/// Ref type alias for [`StellarValueExt`].
pub type StellarValueExtRef = XdrRef<StellarValueExt>;

impl StellarValueExt {
    /// Validate the XDR encoding of StellarValueExt at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: StellarValueType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                StellarValueType::Basic => {}
                StellarValueType::Signed => {
                    let l = LedgerCloseValueSignature::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<StellarValueExt>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<StellarValueExt>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<StellarValueExt> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<StellarValueType, Error> {
        let v = read_i32_at(buf, self.offset())?;
        v.try_into()
    }

    /// Access the `Signed` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_signed(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<LedgerCloseValueSignature>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != StellarValueType::Signed {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = LedgerCloseValueSignature::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`StellarValueExt`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<StellarValueExt, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        StellarValueExt::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

/// Ref type alias for [`StellarValue`].
pub type StellarValueRef = XdrRef<StellarValue>;

impl StellarValue {
    /// Validate the XDR encoding of StellarValue at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            check_bounds(buf, pos, 40)?;
            pos = pos.checked_add(40).ok_or(Error::LengthExceedsMax)?;
            {
                let count = read_u32_at(buf, pos)?;
                if count > 6 {
                    return Err(Error::LengthExceedsMax);
                }
                pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                for _ in 0..count {
                    {
                        let l = UpgradeType::xdr_ref_validate(buf, pos, limits)?;
                        pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    };
                }
            }
            {
                let l = StellarValueExt::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<StellarValue>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<StellarValue>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<StellarValue> {
    /// Access field `tx_set_hash` at a fixed offset.
    #[inline]
    pub fn tx_set_hash(&self, buf: &[u8]) -> Result<XdrRef<Hash>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(field_off, 32))
    }

    /// Access field `close_time` at a fixed offset.
    #[inline]
    pub fn close_time(&self, buf: &[u8]) -> Result<XdrRef<TimePoint>, Error> {
        let field_off = self
            .offset()
            .checked_add(32)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(field_off, 8))
    }

    /// Access field `upgrades` at a variable offset.
    #[inline]
    pub fn upgrades(&self, buf: &[u8]) -> Result<XdrRef<VecM<UpgradeType, 6>>, Error> {
        let field_off = self
            .offset()
            .checked_add(40)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, field_off, 6, |buf, off| {
            let mut p = off;
            let l = UpgradeType::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(field_off, total))
    }

    /// Access field `ext` (variable offset — scans preceding fields).
    pub fn ext(&self, buf: &[u8]) -> Result<XdrRef<StellarValueExt>, Error> {
        let mut pos = self.offset();
        pos = pos.checked_add(40).ok_or(Error::LengthExceedsMax)?;
        {
            pos = pos
                .checked_add(skip_vec_var(buf, pos, 6, |buf, off| {
                    let mut p = off;
                    let l = UpgradeType::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
                    p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
                })?)
                .ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l = StellarValueExt::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Materialize the full owned [`StellarValue`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<StellarValue, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        StellarValue::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .tx_set_hash(buf)?
            .cmp_in(buf, &other.tx_set_hash(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .close_time(buf)?
            .cmp_in(buf, &other.close_time(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .upgrades(buf)?
            .cmp_in(buf, &other.upgrades(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .ext(buf)?
            .cmp_in(buf, &other.ext(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

