impl XdrRef<ParallelTxsComponent> {
    /// Access field `base_fee` at a variable offset.
    #[inline]
    pub fn base_fee(&self, buf: &[u8]) -> Result<XdrRef<Option<i64>>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let flag = read_u32_at(buf, field_off)?;
        match flag {
            0 => Ok(XdrRef::new(field_off, 4)),
            1 => Ok(XdrRef::new(field_off, 12)),
            _ => Err(Error::Invalid),
        }
    }

    /// Access field `execution_stages` (variable offset — scans preceding fields).
    pub fn execution_stages(
        &self,
        buf: &[u8],
    ) -> Result<XdrRef<VecM<ParallelTxExecutionStage>>, Error> {
        let mut pos = self.offset();
        {
            pos = pos
                .checked_add(skip_option(buf, pos, |buf, off| {
                    let mut p = off;
                    p = p.checked_add(8).ok_or(Error::LengthExceedsMax)?;
                    Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
                })?)
                .ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let total = skip_vec_var(buf, field_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = ParallelTxExecutionStage::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(field_off, total))
    }

    /// Materialize the full owned [`ParallelTxsComponent`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ParallelTxsComponent, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ParallelTxsComponent::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .base_fee(buf)?
            .cmp_in(buf, &other.base_fee(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self.execution_stages(buf)?.cmp_in(
            buf,
            &other.execution_stages(other_buf)?,
            other_buf,
        )?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

