/// Ref type alias for [`TransactionMeta`].
pub type TransactionMetaRef = XdrRef<TransactionMeta>;

impl TransactionMeta {
    /// Validate the XDR encoding of TransactionMeta at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            #[allow(clippy::match_same_arms)]
            match dv {
                0 => {
                    let count = read_u32_at(buf, pos)?;
                    if count > u32::MAX {
                        return Err(Error::LengthExceedsMax);
                    }
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    for _ in 0..count {
                        {
                            let l = OperationMeta::xdr_ref_validate(buf, pos, limits)?;
                            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                        };
                    }
                }
                1 => {
                    let l = TransactionMetaV1::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                2 => {
                    let l = TransactionMetaV2::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                3 => {
                    let l = TransactionMetaV3::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                4 => {
                    let l = TransactionMetaV4::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<TransactionMeta>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<TransactionMeta>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<TransactionMeta> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<i32, Error> {
        read_i32_at(buf, self.offset())
    }

    /// Access the `V0` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v0(&self, buf: &[u8]) -> Result<Option<XdrRef<VecM<OperationMeta>>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 0 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, arm_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = OperationMeta::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(arm_off, total)).map(Some)
    }

    /// Access the `V1` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v1(&self, buf: &[u8]) -> Result<Option<XdrRef<TransactionMetaV1>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 1 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = TransactionMetaV1::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `V2` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v2(&self, buf: &[u8]) -> Result<Option<XdrRef<TransactionMetaV2>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 2 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = TransactionMetaV2::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `V3` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v3(&self, buf: &[u8]) -> Result<Option<XdrRef<TransactionMetaV3>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 3 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = TransactionMetaV3::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `V4` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v4(&self, buf: &[u8]) -> Result<Option<XdrRef<TransactionMetaV4>>, Error> {
        let dv = read_i32_at(buf, self.offset())?;
        if dv != 4 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = TransactionMetaV4::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`TransactionMeta`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<TransactionMeta, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        TransactionMeta::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

