    /// Materialize the full owned [`LedgerCloseMetaV1`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<LedgerCloseMetaV1, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        LedgerCloseMetaV1::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .ext(buf)?
            .cmp_in(buf, &other.ext(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord =
            self.ledger_header(buf)?
                .cmp_in(buf, &other.ledger_header(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .tx_set(buf)?
            .cmp_in(buf, &other.tx_set(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord =
            self.tx_processing(buf)?
                .cmp_in(buf, &other.tx_processing(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self.upgrades_processing(buf)?.cmp_in(
            buf,
            &other.upgrades_processing(other_buf)?,
            other_buf,
        )?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .scp_info(buf)?
            .cmp_in(buf, &other.scp_info(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self.total_byte_size_of_live_soroban_state(buf)?.cmp_in(
            buf,
            &other.total_byte_size_of_live_soroban_state(other_buf)?,
            other_buf,
        )?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord =
            self.evicted_keys(buf)?
                .cmp_in(buf, &other.evicted_keys(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .unused(buf)?
            .cmp_in(buf, &other.unused(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
