/// Ref type alias for [`Hello`].
pub type HelloRef = XdrRef<Hello>;

impl Hello {
    /// Validate the XDR encoding of Hello at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            check_bounds(buf, pos, 44)?;
            pos = pos.checked_add(44).ok_or(Error::LengthExceedsMax)?;
            {
                pos = pos
                    .checked_add(skip_var_opaque(buf, pos, 100)?)
                    .ok_or(Error::LengthExceedsMax)?;
            }
            check_bounds(buf, pos, 40)?;
            pos = pos.checked_add(40).ok_or(Error::LengthExceedsMax)?;
            {
                let l = AuthCert::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            check_bounds(buf, pos, 32)?;
            pos = pos.checked_add(32).ok_or(Error::LengthExceedsMax)?;
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<Hello>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<Hello>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

