/// Ref type alias for [`TimeSlicedPeerDataList`].
pub type TimeSlicedPeerDataListRef = XdrRef<TimeSlicedPeerDataList>;

impl TimeSlicedPeerDataList {
    /// Validate the XDR encoding of TimeSlicedPeerDataList at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        let count = read_u32_at(buf, offset)?;
        if count > 25 {
            return Err(Error::LengthExceedsMax);
        }
        let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
        for _ in 0..count {
            let l = TimeSlicedPeerData::xdr_ref_validate(buf, pos, limits)?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
    }

    /// Validate and construct an `XdrRef<TimeSlicedPeerDataList>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<TimeSlicedPeerDataList>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<TimeSlicedPeerDataList> {
    /// Materialize the full owned [`TimeSlicedPeerDataList`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<TimeSlicedPeerDataList, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        TimeSlicedPeerDataList::read_xdr(&mut cursor)
    }

    /// Compare two typedef refs.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        // Typedef wraps another type; byte comparison is correct for canonical XDR.
        let a = self.as_slice(buf)?;
        let b = other.as_slice(other_buf)?;
        Ok(a.cmp(b))
    }
}

