        let ord = self
            .asset(buf)?
            .cmp_in(buf, &other.asset(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .amount(buf)?
            .cmp_in(buf, &other.amount(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .claimants(buf)?
            .cmp_in(buf, &other.claimants(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
