impl RevokeSponsorshipOp {
    /// Validate the XDR encoding of RevokeSponsorshipOp at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: RevokeSponsorshipType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                RevokeSponsorshipType::LedgerEntry => {
                    let l = LedgerKey::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                RevokeSponsorshipType::Signer => {
                    let l = RevokeSponsorshipOpSigner::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<RevokeSponsorshipOp>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<RevokeSponsorshipOp>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<RevokeSponsorshipOp> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<RevokeSponsorshipType, Error> {
        let v = read_i32_at(buf, self.offset())?;
        v.try_into()
    }

    /// Access the `LedgerEntry` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_ledger_entry(&self, buf: &[u8]) -> Result<Option<XdrRef<LedgerKey>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != RevokeSponsorshipType::LedgerEntry {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = LedgerKey::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `Signer` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_signer(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<RevokeSponsorshipOpSigner>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != RevokeSponsorshipType::Signer {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = RevokeSponsorshipOpSigner::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`RevokeSponsorshipOp`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<RevokeSponsorshipOp, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        RevokeSponsorshipOp::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

/// Ref type alias for [`ClawbackOp`].
pub type ClawbackOpRef = XdrRef<ClawbackOp>;

impl ClawbackOp {
    /// Validate the XDR encoding of ClawbackOp at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let l = Asset::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            {
                let l = MuxedAccount::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            check_bounds(buf, pos, 8)?;
            pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ClawbackOp>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ClawbackOp>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ClawbackOp> {
    /// Access field `asset` at a variable offset.
    #[inline]
    pub fn asset(&self, buf: &[u8]) -> Result<XdrRef<Asset>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let l = Asset::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `from` (variable offset — scans preceding fields).
    pub fn from(&self, buf: &[u8]) -> Result<XdrRef<MuxedAccount>, Error> {
        let mut pos = self.offset();
        {
            let l = Asset::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l = MuxedAccount::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `amount` (variable offset — scans preceding fields).
    pub fn amount(&self, buf: &[u8]) -> Result<XdrRef<i64>, Error> {
        let mut pos = self.offset();
        {
            let l = Asset::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        {
            let l = MuxedAccount::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        Ok(XdrRef::new(field_off, 8))
    }

    /// Materialize the full owned [`ClawbackOp`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ClawbackOp, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ClawbackOp::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .asset(buf)?
            .cmp_in(buf, &other.asset(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .from(buf)?
            .cmp_in(buf, &other.from(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .amount(buf)?
            .cmp_in(buf, &other.amount(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

