/// Ref type alias for [`SorobanAuthorizedInvocation`].
pub type SorobanAuthorizedInvocationRef = XdrRef<SorobanAuthorizedInvocation>;

impl SorobanAuthorizedInvocation {
    /// Validate the XDR encoding of SorobanAuthorizedInvocation at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let l = SorobanAuthorizedFunction::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            {
                let count = read_u32_at(buf, pos)?;
                if count > u32::MAX {
                    return Err(Error::LengthExceedsMax);
                }
                pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                for _ in 0..count {
                    {
                        let l = SorobanAuthorizedInvocation::xdr_ref_validate(buf, pos, limits)?;
                        pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    };
                }
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<SorobanAuthorizedInvocation>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<SorobanAuthorizedInvocation>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<SorobanAuthorizedInvocation> {
    /// Access field `function` at a variable offset.
    #[inline]
    pub fn function(&self, buf: &[u8]) -> Result<XdrRef<SorobanAuthorizedFunction>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let l =
            SorobanAuthorizedFunction::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `sub_invocations` (variable offset — scans preceding fields).
    pub fn sub_invocations(
        &self,
        buf: &[u8],
    ) -> Result<XdrRef<VecM<SorobanAuthorizedInvocation>>, Error> {
        let mut pos = self.offset();
        {
            let l = SorobanAuthorizedFunction::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let total = skip_vec_var(buf, field_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = SorobanAuthorizedInvocation::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(field_off, total))
    }

    /// Materialize the full owned [`SorobanAuthorizedInvocation`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<SorobanAuthorizedInvocation, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        SorobanAuthorizedInvocation::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .function(buf)?
            .cmp_in(buf, &other.function(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self.sub_invocations(buf)?.cmp_in(
            buf,
            &other.sub_invocations(other_buf)?,
            other_buf,
        )?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

