/// Ref type alias for [`PreconditionsV2`].
pub type PreconditionsV2Ref = XdrRef<PreconditionsV2>;

impl PreconditionsV2 {
    /// Validate the XDR encoding of PreconditionsV2 at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let flag = read_u32_at(buf, pos)?;
                match flag {
                    0 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    }
                    1 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                        check_bounds(buf, pos, 16)?;
                        pos = pos.checked_add(16).ok_or(Error::LengthExceedsMax)?;
                    }
                    _ => return Err(Error::Invalid),
                }
            }
            {
                let flag = read_u32_at(buf, pos)?;
                match flag {
                    0 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    }
                    1 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                        check_bounds(buf, pos, 8)?;
                        pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
                    }
                    _ => return Err(Error::Invalid),
                }
            }
            {
                let flag = read_u32_at(buf, pos)?;
                match flag {
                    0 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    }
                    1 => {
                        pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                        check_bounds(buf, pos, 8)?;
                        pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
                    }
                    _ => return Err(Error::Invalid),
                }
            }
            check_bounds(buf, pos, 12)?;
            pos = pos.checked_add(12).ok_or(Error::LengthExceedsMax)?;
            {
                let count = read_u32_at(buf, pos)?;
                if count > 2 {
                    return Err(Error::LengthExceedsMax);
                }
                pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                for _ in 0..count {
                    {
                        let l = SignerKey::xdr_ref_validate(buf, pos, limits)?;
                        pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    };
                }
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<PreconditionsV2>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<PreconditionsV2>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

