/// Ref type alias for [`ClaimAtom`].
pub type ClaimAtomRef = XdrRef<ClaimAtom>;

impl ClaimAtom {
    /// Validate the XDR encoding of ClaimAtom at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: ClaimAtomType = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                ClaimAtomType::V0 => {
                    let l = ClaimOfferAtomV0::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ClaimAtomType::OrderBook => {
                    let l = ClaimOfferAtom::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                ClaimAtomType::LiquidityPool => {
                    let l = ClaimLiquidityAtom::xdr_ref_validate(buf, pos, limits)?;
                    pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                }
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ClaimAtom>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ClaimAtom>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ClaimAtom> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<ClaimAtomType, Error> {
        let v = read_i32_at(buf, self.offset())?;
        v.try_into()
    }

    /// Access the `V0` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_v0(&self, buf: &[u8]) -> Result<Option<XdrRef<ClaimOfferAtomV0>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimAtomType::V0 {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ClaimOfferAtomV0::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `OrderBook` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_order_book(&self, buf: &[u8]) -> Result<Option<XdrRef<ClaimOfferAtom>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimAtomType::OrderBook {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ClaimOfferAtom::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Access the `LiquidityPool` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_liquidity_pool(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<ClaimLiquidityAtom>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != ClaimAtomType::LiquidityPool {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let l = ClaimLiquidityAtom::xdr_ref_validate(buf, arm_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(arm_off, l)).map(Some)
    }

    /// Materialize the full owned [`ClaimAtom`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ClaimAtom, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ClaimAtom::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

