/// Ref type alias for [`ManageOfferSuccessResult`].
pub type ManageOfferSuccessResultRef = XdrRef<ManageOfferSuccessResult>;

impl ManageOfferSuccessResult {
    /// Validate the XDR encoding of ManageOfferSuccessResult at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            {
                let count = read_u32_at(buf, pos)?;
                if count > u32::MAX {
                    return Err(Error::LengthExceedsMax);
                }
                pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                for _ in 0..count {
                    {
                        let l = ClaimAtom::xdr_ref_validate(buf, pos, limits)?;
                        pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    };
                }
            }
            {
                let l = ManageOfferSuccessResultOffer::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<ManageOfferSuccessResult>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<ManageOfferSuccessResult>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<ManageOfferSuccessResult> {
    /// Access field `offers_claimed` at a variable offset.
    #[inline]
    pub fn offers_claimed(&self, buf: &[u8]) -> Result<XdrRef<VecM<ClaimAtom>>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, field_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = ClaimAtom::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(field_off, total))
    }

    /// Access field `offer` (variable offset — scans preceding fields).
    pub fn offer(&self, buf: &[u8]) -> Result<XdrRef<ManageOfferSuccessResultOffer>, Error> {
        let mut pos = self.offset();
        {
            pos = pos
                .checked_add(skip_vec_var(buf, pos, u32::MAX, |buf, off| {
                    let mut p = off;
                    let l = ClaimAtom::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
                    p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                    Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
                })?)
                .ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l = ManageOfferSuccessResultOffer::xdr_ref_validate(
            buf,
            field_off,
            &mut RefLimits::none(),
        )?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Materialize the full owned [`ManageOfferSuccessResult`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<ManageOfferSuccessResult, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        ManageOfferSuccessResult::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord =
            self.offers_claimed(buf)?
                .cmp_in(buf, &other.offers_claimed(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .offer(buf)?
            .cmp_in(buf, &other.offer(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

