/// Ref type alias for [`InnerTransactionResultResult`].
pub type InnerTransactionResultResultRef = XdrRef<InnerTransactionResultResult>;

impl InnerTransactionResultResult {
    /// Validate the XDR encoding of InnerTransactionResultResult at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let dv_ref = validate_i32(buf, offset)?;
            let dv = read_i32_at(buf, offset)?;
            let mut pos = offset.checked_add(4).ok_or(Error::LengthExceedsMax)?;
            let disc: TransactionResultCode = dv.try_into()?;
            #[allow(clippy::match_same_arms)]
            match disc {
                TransactionResultCode::TxSuccess => {
                    let count = read_u32_at(buf, pos)?;
                    if count > u32::MAX {
                        return Err(Error::LengthExceedsMax);
                    }
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    for _ in 0..count {
                        {
                            let l = OperationResult::xdr_ref_validate(buf, pos, limits)?;
                            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                        };
                    }
                }
                TransactionResultCode::TxFailed => {
                    let count = read_u32_at(buf, pos)?;
                    if count > u32::MAX {
                        return Err(Error::LengthExceedsMax);
                    }
                    pos = pos.checked_add(4).ok_or(Error::LengthExceedsMax)?;
                    for _ in 0..count {
                        {
                            let l = OperationResult::xdr_ref_validate(buf, pos, limits)?;
                            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
                        };
                    }
                }
                TransactionResultCode::TxTooEarly => {}
                TransactionResultCode::TxTooLate => {}
                TransactionResultCode::TxMissingOperation => {}
                TransactionResultCode::TxBadSeq => {}
                TransactionResultCode::TxBadAuth => {}
                TransactionResultCode::TxInsufficientBalance => {}
                TransactionResultCode::TxNoAccount => {}
                TransactionResultCode::TxInsufficientFee => {}
                TransactionResultCode::TxBadAuthExtra => {}
                TransactionResultCode::TxInternalError => {}
                TransactionResultCode::TxNotSupported => {}
                TransactionResultCode::TxBadSponsorship => {}
                TransactionResultCode::TxBadMinSeqAgeOrGap => {}
                TransactionResultCode::TxMalformed => {}
                TransactionResultCode::TxSorobanInvalid => {}
                TransactionResultCode::TxFrozenKeyAccessed => {}
                #[allow(unreachable_patterns)]
                _ => return Err(Error::Invalid),
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<InnerTransactionResultResult>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<InnerTransactionResultResult>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<InnerTransactionResultResult> {
    /// Read the discriminant.
    #[inline]
    pub fn discriminant(&self, buf: &[u8]) -> Result<TransactionResultCode, Error> {
        let v = read_i32_at(buf, self.offset())?;
        v.try_into()
    }

    /// Access the `TxSuccess` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_tx_success(
        &self,
        buf: &[u8],
    ) -> Result<Option<XdrRef<VecM<OperationResult>>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != TransactionResultCode::TxSuccess {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, arm_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = OperationResult::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(arm_off, total)).map(Some)
    }

    /// Access the `TxFailed` arm. Returns `Ok(None)` if a different arm is active.
    pub fn as_tx_failed(&self, buf: &[u8]) -> Result<Option<XdrRef<VecM<OperationResult>>>, Error> {
        let disc = self.discriminant(buf)?;
        if disc != TransactionResultCode::TxFailed {
            return Ok(None);
        }
        let arm_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let total = skip_vec_var(buf, arm_off, u32::MAX, |buf, off| {
            let mut p = off;
            let l = OperationResult::xdr_ref_validate(buf, p, &mut RefLimits::none())?;
            p = p.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            Ok(p.checked_sub(off).ok_or(Error::Invalid)?)
        })?;
        Ok(XdrRef::new(arm_off, total)).map(Some)
    }

    /// Materialize the full owned [`InnerTransactionResultResult`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<InnerTransactionResultResult, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        InnerTransactionResultResult::read_xdr(&mut cursor)
    }

    /// Compare two union refs: discriminant first, then arm data.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let d1 = read_i32_at(buf, self.offset())?;
        let d2 = read_i32_at(other_buf, other.offset())?;
        let disc_ord = d1.cmp(&d2);
        if disc_ord != Ordering::Equal {
            return Ok(disc_ord);
        }
        // Same discriminant — compare arm data bytes.
        let arm1_off = self
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm1_len = self.len().checked_sub(4).ok_or(Error::Invalid)?;
        let arm2_off = other
            .offset()
            .checked_add(4)
            .ok_or(Error::LengthExceedsMax)?;
        let arm2_len = other.len().checked_sub(4).ok_or(Error::Invalid)?;
        // For union arms with the same discriminant, the XDR bytes are the same type.
        // Byte comparison is correct for unsigned/opaque. For signed ints or complex
        // types we'd need field-by-field comparison. Use byte comparison as a
        // reasonable default matching the existing derived Ord on the owned type.
        cmp_bytes(buf, arm1_off, arm1_len, other_buf, arm2_off, arm2_len)
    }
}

