impl XdrRef<InnerTransactionResult> {
    /// Access field `fee_charged` at a fixed offset.
    #[inline]
    pub fn fee_charged(&self, buf: &[u8]) -> Result<XdrRef<i64>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(field_off, 8))
    }

    /// Access field `result` at a variable offset.
    #[inline]
    pub fn result(&self, buf: &[u8]) -> Result<XdrRef<InnerTransactionResultResult>, Error> {
        let field_off = self
            .offset()
            .checked_add(8)
            .ok_or(Error::LengthExceedsMax)?;
        let l =
            InnerTransactionResultResult::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `ext` (variable offset — scans preceding fields).
    pub fn ext(&self, buf: &[u8]) -> Result<XdrRef<InnerTransactionResultExt>, Error> {
        let mut pos = self.offset();
        pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
        {
            let l =
                InnerTransactionResultResult::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l =
            InnerTransactionResultExt::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Materialize the full owned [`InnerTransactionResult`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<InnerTransactionResult, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        InnerTransactionResult::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .fee_charged(buf)?
            .cmp_in(buf, &other.fee_charged(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .result(buf)?
            .cmp_in(buf, &other.result(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .ext(buf)?
            .cmp_in(buf, &other.ext(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

