/// Ref type alias for [`TransactionResult`].
pub type TransactionResultRef = XdrRef<TransactionResult>;

impl TransactionResult {
    /// Validate the XDR encoding of TransactionResult at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            check_bounds(buf, pos, 8)?;
            pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
            {
                let l = TransactionResultResult::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            {
                let l = TransactionResultExt::xdr_ref_validate(buf, pos, limits)?;
                pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<TransactionResult>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<TransactionResult>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<TransactionResult> {
    /// Access field `fee_charged` at a fixed offset.
    #[inline]
    pub fn fee_charged(&self, buf: &[u8]) -> Result<XdrRef<i64>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(field_off, 8))
    }

    /// Access field `result` at a variable offset.
    #[inline]
    pub fn result(&self, buf: &[u8]) -> Result<XdrRef<TransactionResultResult>, Error> {
        let field_off = self
            .offset()
            .checked_add(8)
            .ok_or(Error::LengthExceedsMax)?;
        let l = TransactionResultResult::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Access field `ext` (variable offset — scans preceding fields).
    pub fn ext(&self, buf: &[u8]) -> Result<XdrRef<TransactionResultExt>, Error> {
        let mut pos = self.offset();
        pos = pos.checked_add(8).ok_or(Error::LengthExceedsMax)?;
        {
            let l = TransactionResultResult::xdr_ref_validate(buf, pos, &mut RefLimits::none())?;
            pos = pos.checked_add(l).ok_or(Error::LengthExceedsMax)?;
        }
        let field_off = pos;
        let l = TransactionResultExt::xdr_ref_validate(buf, field_off, &mut RefLimits::none())?;
        Ok(XdrRef::new(field_off, l))
    }

    /// Materialize the full owned [`TransactionResult`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<TransactionResult, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        TransactionResult::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .fee_charged(buf)?
            .cmp_in(buf, &other.fee_charged(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .result(buf)?
            .cmp_in(buf, &other.result(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        let ord = self
            .ext(buf)?
            .cmp_in(buf, &other.ext(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

