impl Curve25519Public {
    /// Validate the XDR encoding of Curve25519Public at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            check_bounds(buf, pos, 32)?;
            pos = pos.checked_add(32).ok_or(Error::LengthExceedsMax)?;
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<Curve25519Public>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<Curve25519Public>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

impl XdrRef<Curve25519Public> {
    pub const XDR_FIXED_SIZE: u32 = 32;

    /// Access field `key` at a fixed offset.
    #[inline]
    pub fn key(&self, buf: &[u8]) -> Result<XdrRef<[u8; 32]>, Error> {
        let field_off = self
            .offset()
            .checked_add(0)
            .ok_or(Error::LengthExceedsMax)?;
        Ok(XdrRef::new(field_off, 32))
    }

    /// Materialize the full owned [`Curve25519Public`] from the buffer.
    #[cfg(feature = "std")]
    pub fn materialize(&self, buf: &[u8]) -> Result<Curve25519Public, Error> {
        let s = self.as_slice(buf)?;
        let mut cursor = Limited::new(std::io::Cursor::new(s), Limits::len(s.len()));
        Curve25519Public::read_xdr(&mut cursor)
    }

    /// Field-by-field comparison matching derived `Ord`.
    pub fn cmp_in(&self, buf: &[u8], other: &Self, other_buf: &[u8]) -> Result<Ordering, Error> {
        let ord = self
            .key(buf)?
            .cmp_in(buf, &other.key(other_buf)?, other_buf)?;
        if ord != Ordering::Equal {
            return Ok(ord);
        }
        Ok(Ordering::Equal)
    }
}

