/// Ref type alias for [`SerializedBinaryFuseFilter`].
pub type SerializedBinaryFuseFilterRef = XdrRef<SerializedBinaryFuseFilter>;

impl SerializedBinaryFuseFilter {
    /// Validate the XDR encoding of SerializedBinaryFuseFilter at `offset` in `buf`.
    /// Returns the total XDR byte length.
    pub fn xdr_ref_validate(buf: &[u8], offset: u32, limits: &mut RefLimits) -> Result<u32, Error> {
        limits.with_limited_depth(|limits| {
            let mut pos = offset;
            check_bounds(buf, pos, 56)?;
            pos = pos.checked_add(56).ok_or(Error::LengthExceedsMax)?;
            {
                pos = pos
                    .checked_add(skip_var_opaque(buf, pos, u32::MAX)?)
                    .ok_or(Error::LengthExceedsMax)?;
            }
            Ok(pos.checked_sub(offset).ok_or(Error::Invalid)?)
        })
    }

    /// Validate and construct an `XdrRef<SerializedBinaryFuseFilter>` at `offset`.
    pub fn xdr_ref_from(
        buf: &[u8],
        offset: u32,
        limits: &mut RefLimits,
    ) -> Result<XdrRef<SerializedBinaryFuseFilter>, Error> {
        let len = Self::xdr_ref_validate(buf, offset, limits)?;
        Ok(XdrRef::new(offset, len))
    }
}

